import { execFileSync } from 'child_process';
import { readFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { afterAll, describe, expect, it, vi } from 'vitest';
import { validateCarvdFile } from './fileFormat';

vi.unmock('three');

/**
 * The joinery bench has to open.
 *
 * It is generated by a script and checked by another, and between them they
 * had a hole: one proves the joints go together and the other proves each
 * station does what its note says, but neither ever asked whether the file
 * the app would be handed is one the app will accept. A custom router
 * profile written without the id of the definition it came from sailed past
 * both and met the user as a recovery dialog.
 */
const bench = join(tmpdir(), 'carvd-joinery-bench-test.carvd');

afterAll(() => {
  rmSync(bench, { force: true });
});

describe('the generated joinery bench', () => {
  it('is a file the app will open', () => {
    execFileSync(process.execPath, ['scripts/make-joinery-test-project.cjs', bench], { stdio: 'pipe' });
    const result = validateCarvdFile(JSON.parse(readFileSync(bench, 'utf-8')));
    expect(result.errors).toEqual([]);
    expect(result.valid).toBe(true);
  });
});
